const { useEffect, useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

const Options = ({ label, options, value, onChange }) => (
  <div className="flex min-w-0 flex-col gap-1.5">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="flex flex-wrap gap-1.5">
      {options.map(option => {
        const item = typeof option === "string" ? { value: option, label: option } : option;
        const active = item.value === value;
        return (
          <button
            key={item.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

// 跟随元素尺寸（渐变盒子的宽高决定结束形状、渐变线长度）
const useSize = () => {
  const ref = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => setSize({ width: element.clientWidth, height: element.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, size];
};

const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const STOPS = "#ffe29a, #ff8a5b 60%, #a83279";

// 按规范求结束形状的半径，并给出决定尺寸的参照线（中心到对应的边或角）
const endingShape = (shape, extent, x, y, width, height) => {
  const near = { x: Math.min(x, width - x), y: Math.min(y, height - y) };
  const far = { x: Math.max(x, width - x), y: Math.max(y, height - y) };
  const sideX = x < width - x ? 0 : width;
  const sideY = y < height - y ? 0 : height;
  const farSideX = sideX === 0 ? width : 0;
  const farSideY = sideY === 0 ? height : 0;
  const corners = [[0, 0], [width, 0], [0, height], [width, height]]
    .map(([cx, cy]) => ({ cx, cy, distance: Math.hypot(cx - x, cy - y) }))
    .sort((a, b) => a.distance - b.distance);
  const corner = extent === "closest-corner" ? corners[0] : corners[3];
  if (shape === "circle") {
    if (extent === "closest-side" || extent === "farthest-side") {
      const pick = extent === "closest-side" ? Math.min : Math.max;
      const r = pick(near.x, near.y, ...(extent === "farthest-side" ? [far.x, far.y] : []));
      const horizontal = r === (extent === "closest-side" ? near.x : far.x);
      const target = extent === "closest-side" ? (horizontal ? [sideX, y] : [x, sideY]) : horizontal ? [farSideX, y] : [x, farSideY];
      return { rx: r, ry: r, guides: [[x, y, ...target]] };
    }
    return { rx: corner.distance, ry: corner.distance, guides: [[x, y, corner.cx, corner.cy]] };
  }
  if (extent === "closest-side") return { rx: near.x, ry: near.y, guides: [[x, y, sideX, y], [x, y, x, sideY]] };
  if (extent === "farthest-side") return { rx: far.x, ry: far.y, guides: [[x, y, farSideX, y], [x, y, x, farSideY]] };
  // 椭圆的角关键字：宽高比沿用对应的 side 关键字，再让椭圆恰好经过那个角
  const ratioBase = extent === "closest-corner" ? near : far;
  if (!ratioBase.x || !ratioBase.y) return { rx: 0, ry: 0, guides: [[x, y, corner.cx, corner.cy]] };
  const ratio = ratioBase.x / ratioBase.y;
  const dx = corner.cx - x;
  const dy = corner.cy - y;
  const ry = Math.sqrt((dx * dx) / (ratio * ratio) + dy * dy);
  return { rx: ry * ratio, ry, guides: [[x, y, corner.cx, corner.cy]] };
};

const px = value => `${Math.round(value)}px`;

const EndShape = ({ x, y, rx, ry }) =>
  rx > 0 && ry > 0 ? (
    <>
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-surface" strokeWidth="3" />
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-ink-1" strokeWidth="1.25" strokeDasharray="4 3" />
    </>
  ) : null;

const radialCode = parts => [["background-image: radial-gradient(", ...parts, `${parts.length ? ", " : ""}${STOPS});`]];

const SHAPES = [{ value: "", label: "省略" }, "circle", "ellipse"];
const SIZES = ["closest-side", { value: "", label: "省略" }];
const ratio = (a, b) => (b > 0 ? (a / b).toFixed(2) : "—");

const Component = () => {
  const [shape, setShape] = useState("");
  const [extent, setExtent] = useState("closest-side");
  const [boxWidth, setBoxWidth] = useState(100);
  const [boxRef, { width, height }] = useSize();
  const activeShape = shape || "ellipse";
  const activeExtent = extent || "farthest-corner";
  const { rx, ry } = endingShape(activeShape, activeExtent, width / 2, height / 2, width, height);
  const head = [shape, extent].filter(Boolean).join(" ");
  const gradient = `radial-gradient(${head ? `${head}, ` : ""}${STOPS})`;

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          className="relative h-[180px] rounded-tau-sm shadow-card transition-[width] duration-300 ease-tau-out"
          style={{ width: `${boxWidth}%`, backgroundImage: gradient }}
        >
          <Overlay width={width} height={height}>
            <EndShape x={width / 2} y={height / 2} rx={rx} ry={ry} />
            <Dot x={width / 2} y={height / 2} />
          </Overlay>
        </div>
      }
      code={<Code lines={radialCode(head ? [{ mark: head }] : [])} />}
    >
      <Options label="形状" options={SHAPES} value={shape} onChange={setShape} />
      <Options label="尺寸" options={SIZES} value={extent} onChange={setExtent} />
      <Slider label="盒子宽度" value={boxWidth} min={40} max={100} onChange={setBoxWidth} format={value => `${value}%`} />
      <Readout
        rows={[
          ["生效形状", activeShape],
          ["生效尺寸", activeExtent],
          ["盒子", `${px(width)} × ${px(height)}`],
          ["结束形状", activeShape === "circle" ? `r = ${px(rx)}` : `${px(rx)} × ${px(ry)}`],
          ["rx : ry", ratio(rx, ry)],
          ["宽 : 高", ratio(width, height)],
        ]}
      />
    </Lab>
  );
};

const Item = ({ size }) => {
  return (
  	<div style={{ position: 'relative', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
      <div style={{ width: 250, height: 150, borderRadius: 8, backgroundImage: `radial-gradient(${size} at 100px 50px, #fff 0%, #fff 50%, #000 100%)`}}></div>
      <span style={{ color: 'gray', fontSize: '.8em' }}>{size}</span>
    </div>
  )
}

const Component = () => {
  return (
    <>
    	<div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', padding: '16px', gap: 12 }}>
        <Item size={'closest-corner'} />
        <Item size={'closest-side'} />
        <Item size={'farthest-corner'} />
        <Item size={'farthest-side'} />
      </div>
    </>
  )
}

