  ) : null;

const radialCode = parts => [["background-image: radial-gradient(", ...parts, `${parts.length ? ", " : ""}${STOPS});`]];

const EXTENTS = ["closest-side", "farthest-side", "closest-corner", "farthest-corner"];

const Component = () => {
  const [shape, setShape] = useState("circle");
  const [extent, setExtent] = useState("closest-side");
  const [center, setCenter] = useState({ x: 30, y: 40 });
  const [boxRef, { width, height }] = useSize();
  const x = (center.x / 100) * width;
  const y = (center.y / 100) * height;
  const { rx, ry, guides } = endingShape(shape, extent, x, y, width, height);
  const at = `${center.x}% ${center.y}%`;
  const drag = dragProps(boxRef, (left, top, rect) =>
    setCenter({ x: Math.round((left / rect.width) * 100), y: Math.round((top / rect.height) * 100) })
  );

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          {...drag}
          className="relative h-[200px] w-full cursor-crosshair touch-none rounded-tau-sm shadow-card"
          style={{ backgroundImage: `radial-gradient(${shape} ${extent} at ${at}, ${STOPS})` }}
        >
          <Overlay width={width} height={height}>
            <EndShape x={x} y={y} rx={rx} ry={ry} />
            {guides.map(([x1, y1, x2, y2], index) => (
              <Guide key={index} x1={x1} y1={y1} x2={x2} y2={y2} dashed={false} />
            ))}
            <Dot x={x} y={y} />
          </Overlay>
        </div>
      }
      code={<Code lines={radialCode([`${shape} `, { mark: extent }, " at ", { mark: at }])} />}
    >
      <Options label="形状" options={["circle", "ellipse"]} value={shape} onChange={setShape} />
      <Options label="<radial-extent>" options={EXTENTS} value={extent} onChange={setExtent} />
      <span className="text-tau-meta text-ink-3">在左侧拖动可移动渐变中心，实线是决定大小的那段距离。</span>
      <Readout
        rows={[
          ["到左 / 右边", `${px(x)} / ${px(width - x)}`],
          ["到上 / 下边", `${px(y)} / ${px(height - y)}`],
          ["结束形状", shape === "circle" ? `r = ${px(rx)}` : `${px(rx)} × ${px(ry)}`],
        ]}
      />
    </Lab>
  );
};

const { useEffect, useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

const Options = ({ label, options, value, onChange }) => (
  <div className="flex min-w-0 flex-col gap-1.5">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="flex flex-wrap gap-1.5">
      {options.map(option => {
        const item = typeof option === "string" ? { value: option, label: option } : option;
        const active = item.value === value;
        return (
          <button
            key={item.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

const Readout = ({ rows }) => (
  <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1 border-t border-line-2 pt-2.5 text-tau-sm">
    {rows.map(([label, value]) => (
      <React.Fragment key={label}>
        <dt className="text-ink-3">{label}</dt>
        <dd className="m-0 min-w-0 break-all text-right font-tau-mono text-ink-1">{value}</dd>
      </React.Fragment>
    ))}
  </dl>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

// 跟随元素尺寸（渐变盒子的宽高决定结束形状、渐变线长度）
const useSize = () => {
  const ref = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => setSize({ width: element.clientWidth, height: element.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, size];
};

// 浏览器能检测时以实测为准，否则回退到语法解析结论
const supports = value => {
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return null;
  return CSS.supports("background-image", value);
};

const Verdict = ({ valid }) =>
  valid ? (
    <span className="inline-flex items-center gap-1.5 self-start rounded-full bg-ok-soft px-2.5 py-0.5 text-tau-meta text-ok">
      <icons.Check className="size-3.5" />
      声明有效
    </span>
  ) : (
    <span className="inline-flex items-center gap-1.5 self-start rounded-full bg-danger-soft px-2.5 py-0.5 text-tau-meta text-danger">
      <icons.X className="size-3.5" />
      声明无效，整条被丢弃
    </span>
  );

const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const STOPS = "#ffe29a, #ff8a5b 60%, #a83279";

const px = value => `${Math.round(value)}px`;

const EndShape = ({ x, y, rx, ry }) =>
  rx > 0 && ry > 0 ? (
    <>
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-surface" strokeWidth="3" />
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-ink-1" strokeWidth="1.25" strokeDasharray="4 3" />
    </>
  ) : null;

const radialCode = parts => [["background-image: radial-gradient(", ...parts, `${parts.length ? ", " : ""}${STOPS});`]];

const SHAPES = [{ value: "", label: "省略" }, "circle", "ellipse"];
const COUNTS = [{ value: 1, label: "一个值" }, { value: 2, label: "两个值" }];
const UNITS = ["px", "%"];

const Component = () => {
  const [shape, setShape] = useState("");
  const [count, setCount] = useState(1);
  const [unit, setUnit] = useState("px");
  const [sizeX, setSizeX] = useState(80);
  const [sizeY, setSizeY] = useState(50);
  const [boxRef, { width, height }] = useSize();
  const max = unit === "px" ? 200 : 100;
  const valueX = Math.min(sizeX, max);
  const valueY = Math.min(sizeY, max);
  const size = count === 2 ? `${valueX}${unit} ${valueY}${unit}` : `${valueX}${unit}`;
  const head = [shape, size].filter(Boolean).join(" ");
  const gradient = `radial-gradient(${head}, ${STOPS})`;
  // 一个值只能是长度且形状为 circle；两个值形状为 ellipse，可用百分比
  const ruleValid = count === 1 ? unit === "px" && shape !== "ellipse" : shape !== "circle";
  const valid = supports(gradient) ?? ruleValid;
  const toPxX = value => (unit === "%" ? (value / 100) * width : value);
  const toPxY = value => (unit === "%" ? (value / 100) * height : value);
  const rx = toPxX(valueX);
  const ry = count === 2 ? toPxY(valueY) : rx;

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          className={`relative grid h-[200px] w-full place-items-center rounded-tau-sm ${valid ? "shadow-card" : "border border-dashed border-line-1"}`}
          style={valid ? { backgroundImage: gradient } : undefined}
        >
          {valid ? (
            <Overlay width={width} height={height}>
              <EndShape x={width / 2} y={height / 2} rx={rx} ry={ry} />
              <Dot x={width / 2} y={height / 2} />
            </Overlay>
          ) : (
            <span className="text-tau-meta text-ink-3">声明被丢弃，盒子没有背景</span>
          )}
        </div>
      }
      code={<Code lines={radialCode([shape ? `${shape} ` : "", { mark: size }])} />}
    >
      <Options label="形状" options={SHAPES} value={shape} onChange={setShape} />
      <div className="flex flex-wrap gap-x-4 gap-y-3">
        <Options label="值的个数" options={COUNTS} value={count} onChange={setCount} />
        <Options label="单位" options={UNITS} value={unit} onChange={setUnit} />
      </div>
      <Slider label={count === 2 ? "x 方向" : "半径"} value={valueX} min={5} max={max} onChange={setSizeX} format={value => `${value}${unit}`} />
      {count === 2 && (
        <Slider label="y 方向" value={valueY} min={5} max={max} onChange={setSizeY} format={value => `${value}${unit}`} />
      )}
      <Verdict valid={valid} />
      {valid && (
        <Readout
          rows={[
            ["生效形状", count === 2 ? "ellipse" : "circle"],
            ["结束形状", count === 2 ? `${px(rx)} × ${px(ry)}` : `r = ${px(rx)}`],
          ]}
        />
      )}
    </Lab>
  );
};

