    const element = ref.current;
    if (!element) return;
    const measure = () => setSize({ width: element.clientWidth, height: element.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, size];
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
// 在元素上按下并拖动：回调盒内坐标（CSS 像素）与盒子尺寸
const dragProps = (ref, onMove) => {
  const move = event => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect?.width || !rect.height) return;
    onMove(clamp(event.clientX - rect.left, 0, rect.width), clamp(event.clientY - rect.top, 0, rect.height), rect);
  };
  return {
    onPointerDown: event => {
      event.currentTarget.setPointerCapture?.(event.pointerId);
      move(event);
    },
    onPointerMove: event => {
      if (event.buttons & 1) move(event);
    },
  };
};

const H_KEYWORDS = { left: 0, center: 50, right: 100 };
const V_KEYWORDS = { top: 0, center: 50, bottom: 100 };
const isLength = token => /^-?\d*\.?\d+(px|%)$/.test(token) || token === "0";
const toPx = (token, total) => (token.endsWith("%") ? (parseFloat(token) / 100) * total : parseFloat(token));
const axisPx = (token, keywords, total) => (token in keywords ? (keywords[token] / 100) * total : toPx(token, total));

// 按 <position> 语法解析为盒内坐标；不合语法返回 null
const parsePosition = (text, width, height) => {
  const tokens = text.trim().split(/\s+/);
  const isX = token => token in H_KEYWORDS || isLength(token);
  const isY = token => token in V_KEYWORDS || isLength(token);
  if (tokens.length === 1) {
    const [token] = tokens;
    if (token === "top" || token === "bottom") return { x: width / 2, y: axisPx(token, V_KEYWORDS, height) };
    if (isX(token)) return { x: axisPx(token, H_KEYWORDS, width), y: height / 2 };
    return null;
  }
  if (tokens.length === 2) {
    const [first, second] = tokens;
    if (isX(first) && isY(second)) return { x: axisPx(first, H_KEYWORDS, width), y: axisPx(second, V_KEYWORDS, height) };
    // 只有两个都是关键字时才能互换顺序
    if (first in V_KEYWORDS && second in H_KEYWORDS) return { x: axisPx(second, H_KEYWORDS, width), y: axisPx(first, V_KEYWORDS, height) };
    return null;
  }
  if (tokens.length === 4) {
    const pairs = [tokens.slice(0, 2), tokens.slice(2)];
    const horizontal = pairs.find(([edge]) => edge === "left" || edge === "right");
    const vertical = pairs.find(([edge]) => edge === "top" || edge === "bottom");
    if (!horizontal || !vertical || !isLength(horizontal[1]) || !isLength(vertical[1])) return null;
    const x = toPx(horizontal[1], width);
    const y = toPx(vertical[1], height);
    return { x: horizontal[0] === "left" ? x : width - x, y: vertical[0] === "top" ? y : height - y };
  }
  return null;
};

// 浏览器能检测时以实测为准，否则回退到语法解析结论
const supports = value => {
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return null;
  return CSS.supports("background-image", value);
};

const Verdict = ({ valid }) =>
  valid ? (
    <span className="inline-flex items-center gap-1.5 self-start rounded-full bg-ok-soft px-2.5 py-0.5 text-tau-meta text-ok">
      <icons.Check className="size-3.5" />
      声明有效
    </span>
  ) : (
    <span className="inline-flex items-center gap-1.5 self-start rounded-full bg-danger-soft px-2.5 py-0.5 text-tau-meta text-danger">
      <icons.X className="size-3.5" />
      声明无效，整条被丢弃
    </span>
  );

// 辅助线：底下垫一层 surface 色描边，在任何渐变色上都清晰
const Guide = ({ dashed = true, ...props }) => (
  <>
    <line {...props} className="stroke-surface" strokeWidth="3" strokeLinecap="round" />
    <line {...props} className="stroke-ink-1" strokeWidth="1.25" strokeDasharray={dashed ? "4 3" : undefined} />
  </>
);
const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const STOPS = "#ffe29a, #ff8a5b 60%, #a83279";

const px = value => `${Math.round(value)}px`;

const EndShape = ({ x, y, rx, ry }) =>
  rx > 0 && ry > 0 ? (
    <>
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-surface" strokeWidth="3" />
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-ink-1" strokeWidth="1.25" strokeDasharray="4 3" />
    </>
  ) : null;

const radialCode = parts => [["background-image: radial-gradient(", ...parts, `${parts.length ? ", " : ""}${STOPS});`]];

const PRESETS = ["50px 100px", "100px 50px", "25% 75%", "left 50px", "50px top", "50px left", "top 50px"];
const RADIUS = 50;

const Component = () => {
  const [position, setPosition] = useState("50px 100px");
  const [boxRef, { width, height }] = useSize();
  const gradient = `radial-gradient(circle ${RADIUS}px at ${position}, ${STOPS})`;
  const point = parsePosition(position, width, height);
  const valid = supports(gradient) ?? point !== null;
  const [first, second] = position.split(" ");
  const drag = dragProps(boxRef, (x, y) => setPosition(`${Math.round(x)}px ${Math.round(y)}px`));

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          {...drag}
          className={`relative grid h-[200px] w-full cursor-crosshair touch-none place-items-center rounded-tau-sm ${
            valid ? "shadow-card" : "border border-dashed border-line-1"
          }`}
          style={valid ? { backgroundImage: gradient } : undefined}
        >
          {valid && point ? (
            <Overlay width={width} height={height}>
              <Guide x1={0} y1={point.y} x2={point.x} y2={point.y} dashed={false} />
              <Guide x1={point.x} y1={0} x2={point.x} y2={point.y} dashed={false} />
              <EndShape x={point.x} y={point.y} rx={RADIUS} ry={RADIUS} />
              <Dot x={point.x} y={point.y} />
            </Overlay>
          ) : (
            <span className="pointer-events-none text-tau-meta text-ink-3">声明被丢弃，盒子没有背景</span>
          )}
        </div>
      }
      code={<Code lines={radialCode([`circle ${RADIUS}px at `, { mark: position }])} />}
    >
      <Options label="at <position>（双值）" options={PRESETS} value={position} onChange={setPosition} />
      <span className="text-tau-meta text-ink-3">也可以在左侧拖动，写成两个长度。</span>
      <Verdict valid={valid} />
      <Readout
        rows={[
          ["第一个值 → x", valid ? first : "—"],
          ["第二个值 → y", valid ? second : "—"],
        ]}
      />
    </Lab>
  );
