const { useEffect, useRef, useState } = React;

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 16px 16px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

// 实验台骨架：左侧舞台放被演示元素，右侧面板放参数，底部是实时生成的声明
const Lab = ({ stage, children, code }) => (
  <div className="@container flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
      <div className="cb-grid relative flex min-w-0 items-center justify-center rounded-tau-md border border-line-1 p-4">
        {stage}
      </div>
      <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">{children}</div>
    </div>
    {code}
  </div>
);

const Options = ({ label, options, value, onChange }) => (
  <div className="flex min-w-0 flex-col gap-1.5">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="flex flex-wrap gap-1.5">
      {options.map(option => {
        const item = typeof option === "string" ? { value: option, label: option } : option;
        const active = item.value === value;
        return (
          <button
            key={item.value}
            type="button"
            aria-pressed={active}
            onClick={() => onChange(item.value)}
            className={`max-w-full cursor-pointer rounded-tau-sm border px-2 py-0.5 text-left font-tau-mono text-tau-sm transition-colors ${
              active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        );
      })}
    </div>
  </div>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-0 flex-col gap-1">
    <span className="flex items-baseline justify-between gap-2 text-tau-sm text-ink-3">
      <span>{label}</span>
      <span className="font-tau-mono text-ink-1">{format(value)}</span>
    </span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 w-full cursor-pointer"
    />
  </label>
);

// 声明读数：每行由字符串和 { mark } 段组成，mark 段是当前正在调的参数
const Code = ({ lines }) => (
  <code className="block min-w-0 break-all rounded-tau-md bg-hover px-3 py-2 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, lineIndex) => (
      <div key={lineIndex}>
        {line.map((part, index) =>
          typeof part === "string" ? (
            <span key={index}>{part}</span>
          ) : (
            <span key={index} className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">
              {part.mark}
            </span>
          )
        )}
      </div>
    ))}
  </code>
);

// 跟随元素尺寸（渐变盒子的宽高决定结束形状、渐变线长度）
const useSize = () => {
  const ref = useRef(null);
  const [size, setSize] = useState({ width: 0, height: 0 });
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const measure = () => setSize({ width: element.clientWidth, height: element.clientHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, size];
};

const H_KEYWORDS = { left: 0, center: 50, right: 100 };
const V_KEYWORDS = { top: 0, center: 50, bottom: 100 };
const isLength = token => /^-?\d*\.?\d+(px|%)$/.test(token) || token === "0";
const toPx = (token, total) => (token.endsWith("%") ? (parseFloat(token) / 100) * total : parseFloat(token));
const axisPx = (token, keywords, total) => (token in keywords ? (keywords[token] / 100) * total : toPx(token, total));

// 按 <position> 语法解析为盒内坐标；不合语法返回 null
const parsePosition = (text, width, height) => {
  const tokens = text.trim().split(/\s+/);
  const isX = token => token in H_KEYWORDS || isLength(token);
  const isY = token => token in V_KEYWORDS || isLength(token);
  if (tokens.length === 1) {
    const [token] = tokens;
    if (token === "top" || token === "bottom") return { x: width / 2, y: axisPx(token, V_KEYWORDS, height) };
    if (isX(token)) return { x: axisPx(token, H_KEYWORDS, width), y: height / 2 };
    return null;
  }
  if (tokens.length === 2) {
    const [first, second] = tokens;
    if (isX(first) && isY(second)) return { x: axisPx(first, H_KEYWORDS, width), y: axisPx(second, V_KEYWORDS, height) };
    // 只有两个都是关键字时才能互换顺序
    if (first in V_KEYWORDS && second in H_KEYWORDS) return { x: axisPx(second, H_KEYWORDS, width), y: axisPx(first, V_KEYWORDS, height) };
    return null;
  }
  if (tokens.length === 4) {
    const pairs = [tokens.slice(0, 2), tokens.slice(2)];
    const horizontal = pairs.find(([edge]) => edge === "left" || edge === "right");
    const vertical = pairs.find(([edge]) => edge === "top" || edge === "bottom");
    if (!horizontal || !vertical || !isLength(horizontal[1]) || !isLength(vertical[1])) return null;
    const x = toPx(horizontal[1], width);
    const y = toPx(vertical[1], height);
    return { x: horizontal[0] === "left" ? x : width - x, y: vertical[0] === "top" ? y : height - y };
  }
  return null;
};

// 辅助线：底下垫一层 surface 色描边，在任何渐变色上都清晰
const Guide = ({ dashed = true, ...props }) => (
  <>
    <line {...props} className="stroke-surface" strokeWidth="3" strokeLinecap="round" />
    <line {...props} className="stroke-ink-1" strokeWidth="1.25" strokeDasharray={dashed ? "4 3" : undefined} />
  </>
);
const Dot = ({ x, y }) => <circle cx={x} cy={y} r="4.5" className="fill-surface stroke-ink-1" strokeWidth="1.5" />;
const Label = ({ x, y, children, anchor = "middle" }) => (
  <text
    x={x}
    y={y}
    textAnchor={anchor}
    dominantBaseline="middle"
    className="fill-ink-1 stroke-surface font-tau-mono text-tau-tiny"
    strokeWidth="3"
    style={{ paintOrder: "stroke" }}
  >
    {children}
  </text>
);
const Overlay = ({ width, height, children }) =>
  width > 0 && height > 0 ? (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="pointer-events-none absolute inset-0 size-full overflow-hidden rounded-tau-sm"
    >
      {children}
    </svg>
  ) : null;

const STOPS = "#ffe29a, #ff8a5b 60%, #a83279";

const px = value => `${Math.round(value)}px`;

const EndShape = ({ x, y, rx, ry }) =>
  rx > 0 && ry > 0 ? (
    <>
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-surface" strokeWidth="3" />
      <ellipse cx={x} cy={y} rx={rx} ry={ry} fill="none" className="stroke-ink-1" strokeWidth="1.25" strokeDasharray="4 3" />
    </>
  ) : null;

const radialCode = parts => [["background-image: radial-gradient(", ...parts, `${parts.length ? ", " : ""}${STOPS});`]];

const ORDERS = [{ value: "xy", label: "水平在前" }, { value: "yx", label: "垂直在前" }];
const RADIUS = 50;

const Component = () => {
  const [edgeX, setEdgeX] = useState("right");
  const [offsetX, setOffsetX] = useState(40);
  const [edgeY, setEdgeY] = useState("top");
  const [offsetY, setOffsetY] = useState(30);
  const [order, setOrder] = useState("xy");
  const [boxRef, { width, height }] = useSize();
  const partX = `${edgeX} ${offsetX}px`;
  const partY = `${edgeY} ${offsetY}px`;
  const position = order === "xy" ? `${partX} ${partY}` : `${partY} ${partX}`;
  const point = parsePosition(position, width, height) ?? { x: 0, y: 0 };
  const fromX = edgeX === "left" ? 0 : width;
  const fromY = edgeY === "top" ? 0 : height;

  return (
    <Lab
      stage={
        <div
          ref={boxRef}
          className="relative h-[200px] w-full rounded-tau-sm shadow-card"
          style={{ backgroundImage: `radial-gradient(circle ${RADIUS}px at ${position}, ${STOPS})` }}
        >
          <Overlay width={width} height={height}>
            <EndShape x={point.x} y={point.y} rx={RADIUS} ry={RADIUS} />
            <Guide x1={fromX} y1={point.y} x2={point.x} y2={point.y} dashed={false} />
            <Guide x1={point.x} y1={fromY} x2={point.x} y2={point.y} dashed={false} />
            <Label x={(fromX + point.x) / 2} y={point.y - 10}>{`${edgeX} ${offsetX}px`}</Label>
            <Label x={point.x + 8} y={(fromY + point.y) / 2} anchor="start">{`${edgeY} ${offsetY}px`}</Label>
            <Dot x={point.x} y={point.y} />
          </Overlay>
        </div>
      }
      code={
        <Code
          lines={radialCode([
            `circle ${RADIUS}px at `,
            ...(order === "xy" ? [{ mark: partX }, " ", { mark: partY }] : [{ mark: partY }, " ", { mark: partX }]),
          ])}
        />
      }
    >
      <div className="flex flex-wrap gap-x-4 gap-y-3">
        <Options label="水平参照边" options={["left", "right"]} value={edgeX} onChange={setEdgeX} />
        <Options label="垂直参照边" options={["top", "bottom"]} value={edgeY} onChange={setEdgeY} />
      </div>
      <Slider label={`距 ${edgeX}`} value={offsetX} min={-40} max={200} onChange={setOffsetX} format={value => `${value}px`} />
      <Slider label={`距 ${edgeY}`} value={offsetY} min={-40} max={160} onChange={setOffsetY} format={value => `${value}px`} />
      <Options label="书写顺序" options={ORDERS} value={order} onChange={setOrder} />
      <span className="text-tau-meta text-ink-3">每对都带着参照边，交换两对的顺序结果不变；偏移可以为负。</span>
    </Lab>
  );
};

