    </>
  ) : null;

const COLORS = ["#12c2e9", "#c471ed", "#f64f59"];
const MODES = [{ value: "auto", label: "省略位置" }, { value: "explicit", label: "写出位置" }];
const BALL = 200;

const Component = () => {
  const [mode, setMode] = useState("auto");
  const [positions, setPositions] = useState([0, 50, 100]);
  const written = mode === "explicit" ? positions : [0, 50, 100];
  // 位置小于前一个色标时按前一个处理
  const resolved = written.reduce((list, value) => [...list, Math.max(value, list.at(-1) ?? 0)], []);
  const stops = COLORS.map((color, index) => (mode === "explicit" ? `${color} ${positions[index]}%` : color)).join(", ");
  const clamped = written.findIndex((value, index) => value !== resolved[index]);
  const setAt = index => value => setPositions(list => list.map((item, i) => (i === index ? value : item)));

  return (
    <Lab
      stage={
        <div className="flex w-full flex-col items-center gap-3">
          <div
            className="relative size-[200px] rounded-full shadow-card"
            style={{ backgroundImage: `radial-gradient(circle closest-side, ${stops})` }}
          >
            <Overlay width={BALL} height={BALL}>
              {resolved.map((value, index) =>
                value > 0 ? <EndShape key={index} x={BALL / 2} y={BALL / 2} rx={value} ry={value} /> : null
              )}
              <Dot x={BALL / 2} y={BALL / 2} />
            </Overlay>
          </div>
          <div className="flex w-[200px] flex-col gap-1">
            <div className="relative h-2 rounded-full" style={{ backgroundImage: `linear-gradient(to right, ${stops})` }}>
              {resolved.map((value, index) => (
                <span
                  key={index}
                  className="absolute top-1/2 size-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-surface shadow-card"
                  style={{ left: `${value}%`, backgroundColor: COLORS[index] }}
                />
              ))}
            </div>
            <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
              <span>中心 0%</span>
              <span>半径 100%</span>
            </div>
          </div>
        </div>
      }
      code={<Code lines={[["background-image: radial-gradient(circle closest-side, ", { mark: stops }, ");"]]} />}
    >
      <Options label="<color-stop-list>" options={MODES} value={mode} onChange={setMode} />
      {mode === "explicit" &&
        COLORS.map((color, index) => (
          <Slider key={color} label={`第 ${index + 1} 个色标`} value={positions[index]} min={0} max={100} onChange={setAt(index)} format={value => `${value}%`} />
        ))}
      <Readout
        rows={[
          ["解析后", resolved.map(value => `${value}%`).join(" / ")],
          ...(clamped > 0 ? [["说明", `第 ${clamped + 1} 个小于前一个，按 ${resolved[clamped]}% 处理`]] : []),
        ]}
      />
      <span className="text-tau-meta text-ink-3">虚线圈是各色标所在的半径，0% 在中心，100% 落在结束形状上。</span>
    </Lab>
  );
};

